import{_ as r,a0 as d,w as b,s,I as e,x as a,a1 as n,A as l,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"如何在 Ubuntu/Fedora/Debian 中安裝 GitLab | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu/Fedora/Debian 中安裝 GitLab | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu/Fedora/Debian 中安裝 GitLab | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu/Fedora/Debian 中安裝 GitLab | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151109 How to Install GitLab on Ubuntu or Fedora or Debian","title":"如何在 Ubuntu/Fedora/Debian 中安裝 GitLab","tag":"201601","desc":""},"relativePath":"201601/20151109 How to Install GitLab on Ubuntu or Fedora or Debian.md","filePath":"[post].md"}'),p={name:"201601/20151109 How to Install GitLab on Ubuntu or Fedora or Debian.md"};function u(g,t,m,f,h,x){const i=d("Link");return b(),s("div",null,[t[33]||(t[33]=e("h1",{id:"如何在-ubuntu-fedora-debian-中安裝-gitlab",tabindex:"-1"},[a("如何在 Ubuntu/Fedora/Debian 中安裝 GitLab "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-fedora-debian-中安裝-gitlab","aria-label":"Permalink to “如何在 Ubuntu/Fedora/Debian 中安裝 GitLab”"},"​")],-1)),e("p",null,[t[1]||(t[1]=a("在 Git 問世之前，分佈式版本控制從來都不是一件簡單的事。Git 是一個自由開源的軟件，旨在輕鬆且快速地對從小規模到非常巨大的項目進行管理。Git 最開始由 Linus Torvalds 開發，他同時也是著名的 Linux 內核的創建者。在 git 和分佈式版本控制系統領域中，",-1)),n(i,{href:"https://about.gitlab.com/"},{default:l(()=>[...t[0]||(t[0]=[a("GitLab",-1)])]),_:1}),t[2]||(t[2]=a(" 是一個極棒的新產品。它是一個基於 web 的 Git 倉庫管理應用，包含代碼審查、wiki、問題跟蹤等諸多功能。使用 GitLab 可以很方便、快速地創建、審查、部署及託管代碼。儘管它在其官方的服務器提供了與 Github 類似的免費託管的代碼倉庫，但它也可以運行在我們自己的服務器上。GitLab 有兩個不同的版本：社區版(Community Edition)和企業版(Enterprise Edition)。社區版本完全免費且開源，遵循 MIT 協議；而企業版則遵循一個專有的協議，包含一些社區版中沒有的功能。下面介紹的是有關如何在我們自己的運行着 Ubuntu、Fedora 或 Debian 操作系統的機器上安裝 GitLab 社區版的簡單步驟。",-1))]),t[34]||(t[34]=o(`<h3 id="_1-安裝先決條件" tabindex="-1">1. 安裝先決條件 <a class="header-anchor" href="#_1-安裝先決條件" aria-label="Permalink to “1. 安裝先決條件”">​</a></h3><p>首先，我們需要安裝 GitLab 所依賴的軟件包。我們將安裝 <code>curl</code>，用以下載我們所需的文件；安裝<code>openssh-server</code> ，以此來通過 ssh 協議登錄到我們的機器上；安裝<code>ca-certificates</code>，用它來添加 CA 認證；以及 <code>postfix</code>，把它作為一個 MTA(Mail Transfer Agent，郵件傳輸代理)。</p><p>注： 若要安裝 GitLab 社區版，我們需要一個至少包含 2 GB 內存和 2 核 CPU 的 linux 機器。</p><h4 id="在-ubuntu-14-04-debian-8-x-中" tabindex="-1">在 Ubuntu 14 .04/Debian 8.x 中 <a class="header-anchor" href="#在-ubuntu-14-04-debian-8-x-中" aria-label="Permalink to “在 Ubuntu 14 .04/Debian 8.x 中”">​</a></h4><p>鑑於這些依賴包都可以在 Ubuntu 14.04 和 Debian 8.x 的官方軟件倉庫中獲取到，我們只需通過使用 <code>apt-get</code> 包管理器來安裝它們。為此，我們需要在一個終端或控制台中執行下面的命令：</p><pre><code># apt-get install curl openssh-server ca-certificates postfix
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/install-dependencies-gitlab-ubuntu-debian.png" alt="install dependencies gitlab ubuntu debian"></p><h4 id="在-fedora-22-中" tabindex="-1">在 Fedora 22 中 <a class="header-anchor" href="#在-fedora-22-中" aria-label="Permalink to “在 Fedora 22 中”">​</a></h4><p>在 Fedora 22 中，由於 <code>yum</code> 已經被棄用了，默認的包管理器是 <code>dnf</code>。為了安裝上面那些需要的軟件包，我們只需運行下面的 dnf 命令：</p><pre><code># dnf install curl openssh-server postfix
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/install-dependencies-gitlab-fedora.png" alt="install dependencies gitlab fedora"></p><h3 id="_2-打開並開啓服務" tabindex="-1">2. 打開並開啓服務 <a class="header-anchor" href="#_2-打開並開啓服務" aria-label="Permalink to “2. 打開並開啓服務”">​</a></h3><p>現在，我們將使用我們默認的初始化系統來打開 sshd 和 postfix 服務。並且我們將使得它們在每次系統啓動時被自動開啓。</p><h4 id="在-ubuntu-14-04-中" tabindex="-1">在 Ubuntu 14.04 中 <a class="header-anchor" href="#在-ubuntu-14-04-中" aria-label="Permalink to “在 Ubuntu 14.04 中”">​</a></h4><p>由於在 Ubuntu 14.04 中安裝的是 SysVinit 初始化系統，我們將使用 service 命令來開啓 sshd 和 postfix 守護進程：</p><pre><code># service sshd start
# service postfix start
</code></pre><p>現在，為了使得它們在每次開機啓動時被自動開啓，我們需要運行下面的 update-rc.d 命令：</p><pre><code># update-rc.d sshd enable
# update-rc.d postfix enable
</code></pre><h4 id="在-fedora-22-debian-8-x-中" tabindex="-1">在 Fedora 22/Debian 8.x 中 <a class="header-anchor" href="#在-fedora-22-debian-8-x-中" aria-label="Permalink to “在 Fedora 22/Debian 8.x 中”">​</a></h4><p>鑑於 Fedora 22 和 Debian 8.x 已經用 Systemd 代替了 SysVinit 來作為默認的初始化系統，我們只需運行下面的命令來開啓 sshd 和 postfix 服務：</p><pre><code># systemctl start sshd postfix
</code></pre><p>現在，為了使得它們在每次開機啓動時可以自動運行，我們需要運行下面的 systemctl 命令：</p><pre><code># systemctl enable sshd postfix

Created symlink from /etc/systemd/system/multi-user.target.wants/sshd.service to /usr/lib/systemd/system/sshd.service.
Created symlink from /etc/systemd/system/multi-user.target.wants/postfix.service to /usr/lib/systemd/system/postfix.service.
</code></pre><h3 id="_3-下載-gitlab" tabindex="-1">3. 下載 GitLab <a class="header-anchor" href="#_3-下載-gitlab" aria-label="Permalink to “3. 下載 GitLab”">​</a></h3><p>現在，我們將使用 curl 從官方的 GitLab 社區版倉庫下載二進制安裝文件。首先，為了得到所需文件的下載鏈接，我們需要瀏覽到該軟件倉庫的頁面。為此，我們需要在運行着相應操作系統的 linux 機器上運行下面的命令。</p><h4 id="在-ubuntu-14-04-中-1" tabindex="-1">在 Ubuntu 14.04 中 <a class="header-anchor" href="#在-ubuntu-14-04-中-1" aria-label="Permalink to “在 Ubuntu 14.04 中”">​</a></h4>`,26)),e("p",null,[t[4]||(t[4]=a("由於 Ubuntu 和 Debian 使用相同的 debian 格式的安裝包，我們需要在 ",-1)),n(i,{href:"https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs"},{default:l(()=>[...t[3]||(t[3]=[a("https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs",-1)])]),_:1}),t[5]||(t[5]=a(" 下搜索所需版本的 GitLab，然後點擊有着 ubuntu/trusty 標籤的鏈接，即我們運行着的 Ubuntu 14.04。接着一個新的頁面將會出現，我們將看到一個下載按鈕，然後我們在它的上面右擊，得到文件的鏈接，然後像下面這樣使用 curl 來下載它。",-1))]),t[35]||(t[35]=e("pre",null,[e("code",null,`# curl https://packages.gitlab.com/gitlab/gitlab-ce/packages/ubuntu/trusty/gitlab-ce_8.1.2-ce.0_amd64.deb
`)],-1)),t[36]||(t[36]=e("p",null,[e("img",{src:"http://blog.linoxide.com/wp-content/uploads/2015/10/downloading-gitlab-ubuntu.png",alt:"Downloading Gitlab Ubuntu"})],-1)),t[37]||(t[37]=e("h4",{id:"在-debian-8-x-中",tabindex:"-1"},[a("在 Debian 8.x 中 "),e("a",{class:"header-anchor",href:"#在-debian-8-x-中","aria-label":"Permalink to “在 Debian 8.x 中”"},"​")],-1)),e("p",null,[t[7]||(t[7]=a("與 Ubuntu 類似，我們需要在 ",-1)),n(i,{href:"https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs"},{default:l(()=>[...t[6]||(t[6]=[a("https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs",-1)])]),_:1}),t[8]||(t[8]=a(" 頁面中搜索所需版本的 GitLab，然後點擊帶有 debian/jessie 標籤的鏈接，即我們運行着的 Debian 8.x。接着，一個新的頁面將會出現，然後我們在下載按鈕上右擊，得到文件的下載鏈接。最後我們像下面這樣使用 curl 來下載該文件。",-1))]),t[38]||(t[38]=e("pre",null,[e("code",null,`# curl https://packages.gitlab.com/gitlab/gitlab-ce/packages/debian/jessie/gitlab-ce_8.1.2-ce.0_amd64.deb/download
`)],-1)),t[39]||(t[39]=e("p",null,[e("img",{src:"http://blog.linoxide.com/wp-content/uploads/2015/10/downloading-gitlab-debian.png",alt:"Downloading Gitlab Debian"})],-1)),t[40]||(t[40]=e("h4",{id:"在-fedora-22-中-1",tabindex:"-1"},[a("在 Fedora 22 中#### "),e("a",{class:"header-anchor",href:"#在-fedora-22-中-1","aria-label":"Permalink to “在 Fedora 22 中####”"},"​")],-1)),e("p",null,[t[10]||(t[10]=a("由於 Fedora 使用 rpm 文件來作為軟件包，我們將在 ",-1)),n(i,{href:"https://packages.gitlab.com/gitlab/gitlab-ce?filter=rpms"},{default:l(()=>[...t[9]||(t[9]=[a("https://packages.gitlab.com/gitlab/gitlab-ce?filter=rpms",-1)])]),_:1}),t[11]||(t[11]=a(" 頁面下搜索所需版本的 GitLab，然後點擊所需發行包的鏈接，這裏由於我們運行的是 Fedora 22，所以我們將選擇帶有 el/7 標籤的發行包。一個新的頁面將會出現，在其中我們可以看到一個下載按鈕，我們將右擊它，得到所需文件的鏈接，然後像下面這樣使用 curl 來下載它。",-1))]),t[41]||(t[41]=o(`<pre><code># curl https://packages.gitlab.com/gitlab/gitlab-ce/packages/el/7/gitlab-ce-8.1.2-ce.0.el7.x86_64.rpm/download
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/downloading-gitlab-fedora.png" alt="Downloading Gitlab Fedora"></p><h3 id="_4-安裝-gitlab" tabindex="-1">4. 安裝 GitLab <a class="header-anchor" href="#_4-安裝-gitlab" aria-label="Permalink to “4. 安裝 GitLab”">​</a></h3><p>在相應的軟件源被添加到我們的 linux 機器上之後，現在我們將使用相應 linux 發行版本中的默認包管理器來安裝 GitLab 社區版。</p><h4 id="在-ubuntu-14-04-debian-8-x-中-1" tabindex="-1">在 Ubuntu 14.04/Debian 8.x 中 <a class="header-anchor" href="#在-ubuntu-14-04-debian-8-x-中-1" aria-label="Permalink to “在 Ubuntu 14.04/Debian 8.x 中”">​</a></h4><p>要在運行着 Ubuntu 14.04 或 Debian 8.x linux 發行版本的機器上安裝 GitLab 社區版，我們只需運行如下的命令：</p><pre><code># dpkg -i gitlab-ce_8.1.2-ce.0_amd64.deb
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/installing-gitlab-ubuntu-debian.png" alt="Installing Gitlab Ubuntu Debian"></p><h4 id="在-fedora-22-中-2" tabindex="-1">在 Fedora 22 中 <a class="header-anchor" href="#在-fedora-22-中-2" aria-label="Permalink to “在 Fedora 22 中”">​</a></h4><p>我們只需執行下面的 dnf 命令來在我們的 Fedora 22 機器上安裝 GitLab。</p><pre><code># dnf install gitlab-ce-8.1.2-ce.0.el7.x86_64.rpm
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/installing-gitlab-fedora.png" alt="Installing Gitlab Fedora"></p><h3 id="_5-配置和開啓-gitlab" tabindex="-1">5. 配置和開啓 GitLab <a class="header-anchor" href="#_5-配置和開啓-gitlab" aria-label="Permalink to “5. 配置和開啓 GitLab”">​</a></h3><p>GitLab 社區版已經成功地安裝在我們的 linux 系統中了，接下來我們將要配置和開啓它了。為此，我們需要運行下面的命令，這在 Ubuntu、Debian 和 Fedora 發行版本上都一樣：</p><pre><code># gitlab-ctl reconfigure
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/reconfiguring-gitlab.png" alt="Reconfiguring Gitlab"></p><h3 id="_6-允許通過防火牆" tabindex="-1">6. 允許通過防火牆 <a class="header-anchor" href="#_6-允許通過防火牆" aria-label="Permalink to “6. 允許通過防火牆”">​</a></h3><p>假如在我們的 linux 機器中已經啓用了防火牆程序，為了使得 GitLab 社區版的 web 界面可以通過網絡進行訪問，我們需要允許 80 端口通過防火牆，這個端口是 GitLab 社區版的默認端口。為此，我們需要運行下面的命令。</p><h4 id="在-iptables-中" tabindex="-1">在 iptables 中 <a class="header-anchor" href="#在-iptables-中" aria-label="Permalink to “在 iptables 中”">​</a></h4><p>Ubuntu 14.04 默認安裝和使用的是 iptables。所以，我們將運行下面的 iptables 命令來打開 80 端口：</p><pre><code># iptables -A INPUT -p tcp -m tcp --dport 80 -j ACCEPT

# /etc/init.d/iptables save
</code></pre><h4 id="在-firewalld-中" tabindex="-1">在 firewalld 中 <a class="header-anchor" href="#在-firewalld-中" aria-label="Permalink to “在 firewalld 中”">​</a></h4><p>由於 Fedora 22 和 Debian 8.x 默認安裝了 systemd，它包含了作為防火牆程序的 firewalld。為了使得 80 端口（http 服務） 能夠通過 firewalld，我們需要執行下面的命令。</p><pre><code># firewall-cmd --permanent --add-service=http

success

# firewall-cmd --reload

success
</code></pre><h3 id="_7-訪問-gitlab-web-界面" tabindex="-1">7. 訪問 GitLab Web 界面 <a class="header-anchor" href="#_7-訪問-gitlab-web-界面" aria-label="Permalink to “7. 訪問 GitLab Web 界面”">​</a></h3>`,25)),e("p",null,[t[14]||(t[14]=a("最後，我們將訪問 GitLab 社區版的 web 界面。為此，我們需要將我們的 web 瀏覽器指向 GitLab 服務器的網址，根據我們的配置，可能是 ",-1)),n(i,{href:"http://ip-address/"},{default:l(()=>[...t[12]||(t[12]=[a("http://ip-address/",-1)])]),_:1}),t[15]||(t[15]=a(" 或 ",-1)),n(i,{href:"http://domain.com/"},{default:l(()=>[...t[13]||(t[13]=[a("http://domain.com/",-1)])]),_:1}),t[16]||(t[16]=a(" 的格式。在我們成功指向該網址後，我們將會看到下面的頁面。",-1))]),t[42]||(t[42]=o('<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/gitlab-login-screen.png" alt="Gitlab Login Screen"></p><p>現在，為了登錄進面板，我們需要點擊登錄按鈕，它將詢問我們的用户名和密碼。然後我們將輸入默認的用户名和密碼，即 <strong>root</strong> 和 <strong>5iveL!fe</strong> 。在登錄進控制面板後，我們將被強制要求為我們的 GitLab root 用户輸入新的密碼。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/setting-new-password-gitlab.png" alt="Setting New Password Gitlab"></p><h3 id="_8-創建倉庫" tabindex="-1">8. 創建倉庫 <a class="header-anchor" href="#_8-創建倉庫" aria-label="Permalink to “8. 創建倉庫”">​</a></h3><p>在我們成功地更改密碼並登錄到我們的控制面板之後，現在，我們將為我們的新項目創建一個新的倉庫。為此，我們需要來到項目欄，然後點擊 <strong>新項目</strong> 綠色按鈕。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/creating-new-projects.png" alt="Creating New Projects"></p><p>接着，我們將被詢問給我們的項目輸入所需的信息和設定，正如下面展示的那樣。我們甚至可以從其他的 git 倉庫提供商和倉庫中導入我們的項目。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/configuring-git-project.png" alt="Creating New Project"></p><p>做完這些後，我們將能夠使用任何包含基本 git 命令列的 Git 客户端來訪問我們的 Git 倉庫。我們可以看到在倉庫中進行的任何活動，例如創建一個里程碑，管理問題，合併請求，管理成員，便籤，Wiki 等。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/gitlab-menu.png" alt="Gitlab Menu"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>',11)),e("p",null,[t[18]||(t[18]=a("GitLab 是一個用來管理 git 倉庫的很棒的開源 web 應用。它有着漂亮的帶有諸多酷炫功能的響應式界面。它還打包有許多酷炫功能，例如管理羣組，分發密鑰，持續集成，查看日誌，廣播消息，鈎子，系統 OAuth 應用，模板等。（注：OAuth 是一個開放標準，允許用户讓第三方應用訪問該用户在某一網站上存儲的私密的資源（如照片，視頻，聯繫人列表），而無需將用户名和密碼提供給第三方應用。--- 摘取自 ",-1)),n(i,{href:"https://zh.wikipedia.org/wiki/OAuth"},{default:l(()=>[...t[17]||(t[17]=[a("維基百科上的 OAuth 詞條",-1)])]),_:1}),t[19]||(t[19]=a("） 它還可以和大量的工具進行交互如 Slack，Hipchat，LDAP，JIRA，Jenkins，有很多類型的鈎子和完整的 API。它至少需要 2 GB 的內存和 2 核 CPU 來流暢運行，支持多達 500 個用户，但它也可以被擴展到多個工作服務器上。",-1))]),t[43]||(t[43]=e("p",null,"假如你有任何的問題，建議，回饋，請將它們寫在下面的評論框中，以便我們可以提升或更新我們的內容。謝謝！",-1)),t[44]||(t[44]=e("hr",null,null,-1)),e("p",null,[t[21]||(t[21]=a("via: ",-1)),n(i,{href:"http://linoxide.com/linux-how-to/install-gitlab-on-ubuntu-fedora-debian/"},{default:l(()=>[...t[20]||(t[20]=[a("http://linoxide.com/linux-how-to/install-gitlab-on-ubuntu-fedora-debian/",-1)])]),_:1})]),e("p",null,[t[25]||(t[25]=a("作者：",-1)),n(i,{href:"http://linoxide.com/author/arunp/"},{default:l(()=>[...t[22]||(t[22]=[a("Arun Pyasi",-1)])]),_:1}),t[26]||(t[26]=a(" 譯者：",-1)),n(i,{href:"https://github.com/FSSlc"},{default:l(()=>[...t[23]||(t[23]=[a("FSSlc",-1)])]),_:1}),t[27]||(t[27]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[24]||(t[24]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[30]||(t[30]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[28]||(t[28]=[a("LCTT",-1)])]),_:1}),t[31]||(t[31]=a(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...t[29]||(t[29]=[a("Linux中國",-1)])]),_:1}),t[32]||(t[32]=a(" 榮譽推出",-1))])])}const L=r(p,[["render",u]]);export{G as __pageData,L as default};
